const b = $input.first().json.body;
const desc = b.descripcion || '';
const cliente = b.clienteNombre || 'Cliente';
const items = (b.items || []).filter(it => it.descripcion);
const lista = items.length
  ? items.map(it => '• ' + it.descripcion + (it.cantidad > 1 ? ' (×' + it.cantidad + ')' : '') + (it.precioUnitario ? ' — $' + parseFloat(it.precioUnitario).toLocaleString('es-MX') : '')).join('
')
  : '• ' + desc;

const prompt = `Eres un especialista en propuestas comerciales para agencias y freelancers. Redacta una propuesta profesional en español para incluir en una cotización.

CLIENTE: ${cliente}
PROYECTO: ${desc}
SERVICIOS:
${lista}

Genera la propuesta con estas secciones en Markdown:

## Resumen del Proyecto
Describe en 2-3 oraciones el objetivo y el valor que entregará este proyecto al cliente.

## Alcance del Trabajo
Detalla específicamente qué incluye cada servicio. Usa bullets concretos y orientados al cliente.

## Entregables
Lista en bullets lo que recibirá el cliente al finalizar el proyecto.

## Proceso de Trabajo
Explica brevemente las etapas, revisiones incluidas y forma de comunicación.

Máximo 380 palabras. Tono profesional y orientado a resultados. No menciones precios.`;

return [{ json: { prompt, apiKey: b.apiKey } }];
